{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "VPC Flow Logs are not enabled",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The data subnet does not configure VPC Flow Logs, limiting visibility into network traffic and reducing the information available for incident investigation."
    }
  ],
  "patched_code": "resource \"google_compute_subnetwork\" \"data_subnet\" {\n  name                     = \"insurance-claims-processing-platform-subnet-data\"\n  ip_cidr_range            = \"10.0.3.0/24\"\n  region                   = var.region\n  network                  = google_compute_network.claims_vpc.id\n  description              = \"Data subnet for Cloud SQL database\"\n  private_ip_google_access = true\n\n  log_config {}\n}\n",
  "fix_summary": "Enabled VPC Flow Logs on the data subnet by adding a log_config block."
}
